window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-669feb7669967c7a"]={"versions": [{"id": "FIG-669feb7669967c7a", "releases": ["R3.0.7", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Prozessdiagramm (Methoden-Workflow) der AUTOSAR Classic Platform. Es visualisiert den standardisierten Top-Level-Engineering-Prozess von der initialen Systemdefinition über die ECU-spezifische Extraktion bis hin zur Generierung der ausführbaren Steuergeräte-Software (<code>.exe</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Prozessaktivitäten (gelbe Blockpfeile) und fünf Artefakte bzw. Beschreibungsdateien (blaue Dokumentensymbole):</p>\n<ul class=\"fig-list\"><li>Artefakte / Datenelemente:\n<ul class=\"fig-list\"><li><code>System Configuration Input : System</code> (<code>.XML</code>): Definition von Softwarekomponenten, Topologie und Systemanforderungen.\n</li><li><code>System Configuration Description : System</code> (<code>.XML</code>): Vollständige Systembeschreibung nach initialer Systemkonfiguration.\n</li><li><code>ECU Extract of System Configuration : System</code> (<code>.XML</code>): Auf ein spezifisches Steuergerät reduzierter Konfigurationsauszug.\n</li><li><code>ECU Configuration</code> (<code>.XML</code>): Detaillierte BSW- und RTE-Konfiguration für das Steuergerät.\n</li><li><code>ECU Executable</code> (<code>.exe</code>): Kompilierte und gebundene binäre Steuergeräte-Firmware.\n</li></ul>\n</li><li>Aktivitäten / Verarbeitungsschritte:\n<ul class=\"fig-list\"><li><code>Configure System</code>: Integriert Komponenten und Netzwerktopologie.\n</li><li><code>Extract ECU-Specific Information</code>: Filtert das Gesamtsystem auf das Ziel-ECU.\n</li><li><code>Configure ECU</code>: Konfiguriert BSW-Module und RTE-Parameter.\n</li><li><code>Generate Executable</code>: Codegenerierung, Kompilierung und Linken des ausführbaren Programms.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Streng sequenzieller, kaskadierter Entwurfsprozess:</p>\n<ol class=\"fig-list\"><li><code>System Configuration Input : System</code> geht als Eingabe in den Schritt <code>Configure System</code>.\n</li><li><code>Configure System</code> erzeugt die <code>System Configuration Description : System</code>.\n</li><li>Aus der <code>System Configuration Description : System</code> wird im Schritt <code>Extract ECU-Specific Information</code> die ECU-spezifische Sicht isoliert.\n</li><li>Dieser Schritt erzeugt das <code>ECU Extract of System Configuration : System</code>.\n</li><li>Auf Basis des ECU-Extrakts erfolgt im Schritt <code>Configure ECU</code> die detaillierte BSW-Konfiguration.\n</li><li><code>Configure ECU</code> liefert die <code>ECU Configuration</code>.\n</li><li><code>Generate Executable</code> nutzt die <code>ECU Configuration</code> zur Generierung und Kompilierung der Zielanwendung.\n</li><li>Das finale Ausgangsprodukt ist das <code>ECU Executable</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Prozesskette der AUTOSAR-Methodik auf Makroebene. Für Werkzeughersteller und Integratoren sind die standardisierten XML-Formate (AUTOSAR XML, ARXML) an den jeweiligen Schnittstellen bindend. Insbesondere bildet das ECU-Extract die normative Übergabeschnittstelle (Demarcation Line) zwischen Fahrzeughersteller (OEM / Gesamtsystemebene) und Tier-1-Zulieferer (ECU-Ebene). Implementierungs-Tools müssen sicherstellen, dass die Übergabeformate dem jeweiligen AUTOSAR-Schema genügen.</p>"}, {"id": "FIG-c40e1472fdfc08f6", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Prozessdiagramm (Methoden-Workflow) der AUTOSAR Classic Platform. Es visualisiert den standardisierten Top-Level-Engineering-Prozess von der initialen Systemdefinition über die ECU-spezifische Extraktion bis hin zur Generierung der ausführbaren Steuergeräte-Software (<code>.exe</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Prozessaktivitäten (gelbe Blockpfeile) und fünf Artefakte bzw. Beschreibungsdateien (blaue Dokumentensymbole):</p>\n<ul class=\"fig-list\"><li>Artefakte / Datenelemente:\n<ul class=\"fig-list\"><li><code>System Configuration Input : System</code> (<code>.XML</code>): Definition von Softwarekomponenten, Topologie und Systemanforderungen.\n</li><li><code>System Configuration Description : System</code> (<code>.XML</code>): Vollständige Systembeschreibung nach initialer Systemkonfiguration.\n</li><li><code>ECU Extract of System Configuration : System</code> (<code>.XML</code>): Auf ein spezifisches Steuergerät reduzierter Konfigurationsauszug.\n</li><li><code>ECU Configuration</code> (<code>.XML</code>): Detaillierte BSW- und RTE-Konfiguration für das Steuergerät.\n</li><li><code>ECU Executable</code> (<code>.exe</code>): Kompilierte und gebundene binäre Steuergeräte-Firmware.\n</li></ul>\n</li><li>Aktivitäten / Verarbeitungsschritte:\n<ul class=\"fig-list\"><li><code>Configure System</code>: Integriert Komponenten und Netzwerktopologie.\n</li><li><code>Extract ECU-Specific Information</code>: Filtert das Gesamtsystem auf das Ziel-ECU.\n</li><li><code>Configure ECU</code>: Konfiguriert BSW-Module und RTE-Parameter.\n</li><li><code>Generate Executable</code>: Codegenerierung, Kompilierung und Linken des ausführbaren Programms.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Streng sequenzieller, kaskadierter Entwurfsprozess:</p>\n<ol class=\"fig-list\"><li><code>System Configuration Input : System</code> geht als Eingabe in den Schritt <code>Configure System</code>.\n</li><li><code>Configure System</code> erzeugt die <code>System Configuration Description : System</code>.\n</li><li>Aus der <code>System Configuration Description : System</code> wird im Schritt <code>Extract ECU-Specific Information</code> die ECU-spezifische Sicht isoliert.\n</li><li>Dieser Schritt erzeugt das <code>ECU Extract of System Configuration : System</code>.\n</li><li>Auf Basis des ECU-Extrakts erfolgt im Schritt <code>Configure ECU</code> die detaillierte BSW-Konfiguration.\n</li><li><code>Configure ECU</code> liefert die <code>ECU Configuration</code>.\n</li><li><code>Generate Executable</code> nutzt die <code>ECU Configuration</code> zur Generierung und Kompilierung der Zielanwendung.\n</li><li>Das finale Ausgangsprodukt ist das <code>ECU Executable</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Prozesskette der AUTOSAR-Methodik auf Makroebene. Für Werkzeughersteller und Integratoren sind die standardisierten XML-Formate (AUTOSAR XML, ARXML) an den jeweiligen Schnittstellen bindend. Insbesondere bildet das ECU-Extract die normative Übergabeschnittstelle (Demarcation Line) zwischen Fahrzeughersteller (OEM / Gesamtsystemebene) und Tier-1-Zulieferer (ECU-Ebene). Implementierungs-Tools müssen sicherstellen, dass die Übergabeformate dem jeweiligen AUTOSAR-Schema genügen.</p>"}], "trans": [{"from": "FIG-669feb7669967c7a", "to": "FIG-c40e1472fdfc08f6", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c40e1472fdfc08f6", "to": "FIG-669feb7669967c7a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
